var wdth = window.innerWidth, hght = window.innerHeight;
var generates = 0;
var attempts = 300;
var mainCirlce = {
  x: wdth / 2,
  y: hght / 2,
  rds: 200
};

var maxCirlcesCount = 700;
var circles = [];
var maxCircleSize = mainCirlce.rds / 7;
var colors = [
  ['#0F4155', '#F5C03E'],
  ['#D63826', '#0F4155'],
  ['#0F4155', '#D63826'],
  ['#152A3B', '#158ca7'],
  ['#e4a50a', '#D63826'],
  ['#D63826', '#e4a50a'],
  ['#3a7b30', '#F5C03E'],
  ['#0F4155', '#7ec873']
];

var mouseCircle = {
  currX: wdth / 2,
  currY: -100,
  targX: wdth / 2,
  targY: -100,
  rds: maxCircleSize * .85,
  easingCircle: .15,
  easingRect: .13,
  angle: Math.random() * 360,
  rectCurrX: wdth / 2,
  rectCurrY: -100,
};

var activeDistance = maxCircleSize * 3;
var isRectPosOfsset = false;
var isRectWidthOfsset = false;
var isDrawBubbles = true;
var isDrawRects = true;
var rndWidthFactor = 1;
var rndXOffsetFactor = .5;
var rndYOffsetFactor = .5;

function setup() {
  createCanvas(wdth, hght);
  angleMode(DEGREES);
  strokeWeight(1);

window.simulatedMouseX = 0;
window.simulatedMouseY = -100;

  generateNewWorld();
}

function generateNewWorld() {
  isRectPosOfsset = false;
  isRectWidthOfsset = false;
  isDrawBubbles = true;
  isDrawRects = true;
  rndWidthFactor = 1;
  rndXOffsetFactor = .5;
  rndYOffsetFactor = .5;

  mouseCircle.angle = random(360);

  var clrSetIdx = ~~random(colors.length);
  stroke(colors[clrSetIdx][0]);
  fill(colors[clrSetIdx][1]);

  if (Math.random() >= .8) {
    isRectWidthOfsset = true;
    rndWidthFactor = random(3, 5);
  }
  if (Math.random() >= .7) {
    isRectPosOfsset = true;
    rndXOffsetFactor = random(-.5, 1);
    rndYOffsetFactor = random(-.5, 1);
  }
  if (Math.random() >= .85) {
    isDrawBubbles = false;
  }

  if (isDrawBubbles) {
    if (Math.random() >= .85) {
      isDrawRects = false;
    }
  }

  generateCirclesInCircle();
}

function draw() {
  background('#fff');
  drawFoamBubbles();
  drawMouseCircle();
}

function drawFoamBubbles() {
  updateCirclesPos(circles);

  circles.forEach(function (p) {
    p.updateAnimationValues();
  });

  if (isDrawRects) {
    circles.forEach(function (p) {
      p.drawRect();
    });
  }

  if (isDrawBubbles) {
    circles.forEach(function (p) {
      p.drawCircle();
    });
  }
}

function drawMouseCircle() {
  mouseCircle.currX += ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - mouseCircle.currX) * mouseCircle.easingCircle;
  mouseCircle.currY += ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - mouseCircle.currY) * mouseCircle.easingCircle;

  mouseCircle.rectCurrX += ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - mouseCircle.rectCurrX) * mouseCircle.easingRect;
  mouseCircle.rectCurrY += ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - mouseCircle.rectCurrY) * mouseCircle.easingRect;

  push();
  noFill();
  ellipse(mouseCircle.currX, mouseCircle.currY, mouseCircle.rds * 2, mouseCircle.rds * 2);
  // ellipse(mouseCircle.currX, mouseCircle.currY, mouseCircle.rds * 2 + .3, mouseCircle.rds * 2 + .3);
  pop();

  push();
  noStroke();
  translate(mouseCircle.rectCurrX, mouseCircle.rectCurrY);
  rotate(mouseCircle.angle);
  rect(-mouseCircle.rds * rndXOffsetFactor, -mouseCircle.rds * rndYOffsetFactor, mouseCircle.rds / rndWidthFactor, mouseCircle.rds);
  pop();
}

function generateCirclesInCircle() {
  circles = [];
  var newCircleCenter, tmpDistance, cDist, idx, itr, i;

  for (idx = 0; idx < maxCirlcesCount; idx++) {
    for (i = 0; i < attempts; ++i) {
      newCircleCenter = genNewPosition(mainCirlce);
      if (isPointInsideCircle(newCircleCenter, mainCirlce) && !isIntersectWithCircles(newCircleCenter, circles)) {
        break;
      }
    }

    // distance to main circle border;
    var newCircleSize = (mainCirlce.rds - dist(newCircleCenter.x, newCircleCenter.y, mainCirlce.x, mainCirlce.y)) * 2;
    newCircleSize = newCircleSize > maxCircleSize ? maxCircleSize : newCircleSize;

    for (itr = 0; itr < circles.length; itr++) {
      cDist = dist(circles[itr].x, circles[itr].y, newCircleCenter.x, newCircleCenter.y);
      tmpDistance = Math.abs(circles[itr].rds - cDist);

      if (tmpDistance < newCircleSize) {
        newCircleSize = tmpDistance + 3;
      }
    }

    if (newCircleSize >= 3) {
      circles.push(new Circle(newCircleCenter.x, newCircleCenter.y, newCircleSize, idx));
    }
  }

  if (isRectWidthOfsset) {
    circles.forEach(function (circleItem) {
      circleItem.rectWidthDivideFactor = rndWidthFactor;
    });
  }
  if (isRectPosOfsset) {
    circles.forEach(function (circleItem) {
      circleItem.rectXOffsetFactor = rndXOffsetFactor;
      circleItem.rectYOffsetFactor = rndYOffsetFactor;
    });
  }
}

function updateCirclesPos() {
  var i, circleItem, theta, distance;

  for (i = 0; i < circles.length; i++) {
    circleItem = circles[i];

    theta = Math.atan2(circleItem.y - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), circleItem.x - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))));
    distance = activeDistance / dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), circleItem.x, circleItem.y);

    circleItem.x += Math.cos(theta) * distance + (circleItem.origX - circleItem.x) * 0.075;
    circleItem.y += Math.sin(theta) * distance + (circleItem.origY - circleItem.y) * 0.075;
  }
}


// Circle class
function Circle (x, y, r, idx) {
  this.x = x;
  this.y = y;
  this.origX = x;
  this.origY = y;
  this.rds = r;
  this.currRds = 0;
  this.idx = idx;
  this.durAnimation = random(1.7, 2.7);
  this.durProgress = 0;
  this.currAngle = random(60, 360);
  this.targetAngle = this.currAngle + random(60, 240) * (Math.random() > .5 ? 1 : -1);

  this.rectWidth = 0;
  this.rectX = 0;
  this.rectY = 0;
  this.rectXOffsetFactor = .5;
  this.rectYOffsetFactor = .5;
  this.rectWidthDivideFactor = 1;

  this.drawCircle = function (/*isNeedCross*/) {
    push();
    noFill();
    ellipse(this.x, this.y, this.currRds * 2, this.currRds * 2);
    // ellipse(this.x, this.y, this.currRds * 2 + .3, this.currRds * 2 + .3);
    pop();

    // if (isNeedCross && this.rds > 3) {
    //   line(this.x - 2, this.y - 2, this.x + 2, this.y + 2);
    //   line(this.x - 2, this.y + 2, this.x + 2, this.y - 2);
    // }
  };

  this.drawRect = function () {
    push();
    noStroke();
    translate(this.x, this.y);
    rotate(this.currAngle);
    rect(this.rectX, this.rectY, this.rectWidth, this.currRds);
    pop();
  };

  this.updateAnimationValues = function () {
    if (this.durProgress < this.durAnimation) {
      if (this.currRds !== this.rds) {
        this.currRds = easeOutElastic(this.durProgress, this.currRds, this.rds, this.durAnimation);
        this.rectWidth = this.currRds / this.rectWidthDivideFactor;
        this.rectX = -this.currRds * this.rectXOffsetFactor;
        this.rectY = -this.currRds * this.rectYOffsetFactor;
      }

      if (this.currAngle !== this.targetAngle) {
        this.currAngle = easeOutElastic(this.durProgress, this.currAngle, this.targetAngle, this.durAnimation);
      }

      this.durProgress += .008;
    }
  };

  this.drawWithAnimate = function () {
    this.updateAnimationValues();
    this.drawCircle();
  };
}

function genNewPosition(mainCirlce) {
  return {
    x: random(10, width  - 20),
    y: random(10, height - 10)
  };

  // // different way: perfect for creating point inside circle but having some slight differences in result
  // var angle = random(TAU);
  // var scalar = random(1, mainCirlce.rds);
  // return {
  //   x: Math.cos(angle) * scalar + mainCirlce.x,
  //   y: Math.sin(angle) * scalar + mainCirlce.y
  // };
}

function isPointInsideCircle(pos, circle) {
  return  dist (pos.x, pos.y, circle.x, circle.y) < circle.rds;
}

function isIntersectWithCircles(pos, circles) {
  if (circles.length > 0) {
    for (var i = 0; i < circles.length; i++) {
      if (isPointInsideCircle(pos, circles[i])) {
        return true;
      }
      // return isPointInsideCircle(pos, circles[i]);
    }
  }

  return false;
}


function keyTyped(evt) {
  var eventKey = evt.key.toLowerCase();
  switch (eventKey){
    case 'g': generateNewWorld(); break;
  }
}

function mousePressed(evt) {
  if (evt.button === 0) { generateNewWorld(); }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}
//////////////////////////////////////////////////////////////////////////////////////////////////////////////
// Helper Functions //////////////////////////////////////////////////////////////////////////////////////////

// t: curr time, b: start val, c: change In value, d: duration
function easeOutElastic(t, b, c, d) {
  var s = 1.70158;
  var a = c;
  if (t === 0) { return 0; }
  t /= d;
  if (t === 1) { return c; }
  var p = d * 0.3;
  if (a < Math.abs(c)) {
    a = c;
    s = p / 4;
  } else {
    s = p / (2 * Math.PI) * Math.asin(c / a);
  }
  return a * Math.pow(2, -10 * t) * Math.sin((t * d - s) * (2 * Math.PI) / p) + c;
}
